import{_ as i,c as e,o as l,a2 as s}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/troubleshooting.md","filePath":"ja/guide/troubleshooting.md","lastUpdated":1793163976000}'),t={name:"ja/guide/troubleshooting.md"};function o(r,a,n,p,h,d){return l(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><p>このページでは、macOS 上の NueZip でよくある問題とその解決方法をまとめています。</p><h2 id="アプリが起動しない、または起動時にクラッシュする" tabindex="-1">アプリが起動しない、または起動時にクラッシュする <a class="header-anchor" href="#アプリが起動しない、または起動時にクラッシュする" aria-label="Permalink to &quot;アプリが起動しない、または起動時にクラッシュする&quot;">​</a></h2><p>症状: NueZip が開かない、すぐにクラッシュする、または予期しないエラーが表示される。</p><p>試すべき手順：</p><ol><li>macOS のバージョンが最小要件（macOS 14 Sonoma+）を満たしていることを確認してください。</li><li>アプリを終了し、再起動してください。</li><li>Mac を再起動してください。</li><li>アプリが GitHub Releases からダウンロードされた場合は、最新のビルドまたは公証済みのバージョンをダウンロードしてみてください。</li><li>問題が続く場合は、ログを収集（以下参照）して issue を作成してください。</li></ol><h2 id="rar-アーカイブを開けない" tabindex="-1">RAR アーカイブを開けない <a class="header-anchor" href="#rar-アーカイブを開けない" aria-label="Permalink to &quot;RAR アーカイブを開けない&quot;">​</a></h2><p>症状: NueZip が <code>.rar</code> ファイルを開けない、またはエラーを表示する。</p><p>チェックリスト：</p><ol><li>RAR ファイルが破損していないことを確認してください。The Unarchiver などの別のツールで開いてみてください。</li><li>マルチボリュームの RAR アーカイブには、すべてのパート（<code>.part1.rar</code>、<code>.part2.rar</code> など）が揃っている必要があります。</li><li>パスワードで保護された RAR アーカイブには、正しいパスワードが必要です。</li><li>RAR5 フォーマットはサポートされています。それより古い RAR フォーマットをお持ちの場合はご報告ください。</li></ol><h2 id="パスワードエラーで展開に失敗する" tabindex="-1">パスワードエラーで展開に失敗する <a class="header-anchor" href="#パスワードエラーで展開に失敗する" aria-label="Permalink to &quot;パスワードエラーで展開に失敗する&quot;">​</a></h2><p>症状: &quot;パスワードが違います&quot; または復号エラーで展開に失敗する。</p><p>チェックリスト：</p><ol><li>パスワードが正しいことを確認してください — パスワードは大文字小文字を区別します。</li><li>正しい暗号化方式がサポートされていることを確認してください（ZIP の場合は AES-256）。</li><li>パスワードマネージャーからパスワードを再入力してみてください。</li></ol><h2 id="finder-機能拡張が表示されない" tabindex="-1">Finder 機能拡張が表示されない <a class="header-anchor" href="#finder-機能拡張が表示されない" aria-label="Permalink to &quot;Finder 機能拡張が表示されない&quot;">​</a></h2><p>症状: Finder でアーカイブを右クリックしても NueZip のオプションが表示されない。</p><p>チェックリスト：</p><ol><li>機能拡張を有効にしてください：システム設定 → プライバシーとセキュリティ → 機能拡張 → Finder 機能拡張 → <strong>NueZip</strong> を有効にする。</li><li>Finder を再起動してください：アクティビティモニタで Finder を右クリック → 再起動、またはターミナルで <code>killall Finder</code> を実行してください。</li><li>それでも機能拡張が表示されない場合は、アプリを再インストールしてください。</li></ol><h2 id="ライセンス-購入が表示されない" tabindex="-1">ライセンス／購入が表示されない <a class="header-anchor" href="#ライセンス-購入が表示されない" aria-label="Permalink to &quot;ライセンス／購入が表示されない&quot;">​</a></h2><p>症状: NueZip を購入したのに、試用版のまま表示される。</p><p>チェックリスト：</p><ol><li>購入に使用したものと同じ Apple ID でサインインしていることを確認してください。</li><li>購入を復元してください：NueZip → 設定 → ライセンス → 購入を復元。</li><li>問題が続く場合はサポートに連絡してください。</li></ol><h2 id="デバッグログの収集方法" tabindex="-1">デバッグログの収集方法 <a class="header-anchor" href="#デバッグログの収集方法" aria-label="Permalink to &quot;デバッグログの収集方法&quot;">​</a></h2><p>問題の診断を支援するため、NueZip からデバッグログを収集します：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 共有のためにログをデスクトップにコピーする</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/NueZip-Logs</span></span></code></pre></div><p>その後、<a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> で issue を作成し、ログを添付してください。</p><h2 id="権限に関する問題" tabindex="-1">権限に関する問題 <a class="header-anchor" href="#権限に関する問題" aria-label="Permalink to &quot;権限に関する問題&quot;">​</a></h2><p>機能が権限を求めたが、許可しても動作しない場合：</p><ol><li>権限を許可した後、アプリを終了して再起動してください。</li><li>必要に応じて、<code>tccutil</code> で権限プロンプトをリセットしてください（<a href="./permissions.html">権限ガイド</a> 参照）。</li></ol><h2 id="パフォーマンスの問題" tabindex="-1">パフォーマンスの問題 <a class="header-anchor" href="#パフォーマンスの問題" aria-label="Permalink to &quot;パフォーマンスの問題&quot;">​</a></h2><p>アプリが遅い、または応答しない場合：</p><ol><li>他の負荷の高いアプリケーションを閉じてください。</li><li>より小さなアーカイブを展開して、問題を切り分けてみてください。</li><li>時間の経過とともにパフォーマンスが低下する場合は、アプリを再起動してください。</li></ol><h2 id="ログを確認する" tabindex="-1">ログを確認する <a class="header-anchor" href="#ログを確認する" aria-label="Permalink to &quot;ログを確認する&quot;">​</a></h2><p>クラッシュや問題のトラブルシューティングには、アプリケーションログが最も役立つ情報です。サンドボックス化された（App Store の）ビルドでは、以下を確認してください：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span></span></code></pre></div><h2 id="アプリのリセット" tabindex="-1">アプリのリセット <a class="header-anchor" href="#アプリのリセット" aria-label="Permalink to &quot;アプリのリセット&quot;">​</a></h2><p>設定をリセットし、ローカルデータをクリアするには：</p><ol><li>NueZip を終了する</li><li>コンテナを削除する（注意 — これによりすべての設定が削除されます）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><ol start="3"><li>NueZip を再起動し、再設定してください。</li></ol><h2 id="問題を報告する" tabindex="-1">問題を報告する <a class="header-anchor" href="#問題を報告する" aria-label="Permalink to &quot;問題を報告する&quot;">​</a></h2><p>issue を作成する際は、以下を含めてください：</p><ul><li>macOS のバージョン（Apple メニュー → この Mac について）</li><li>NueZip のバージョン（NueZip → バージョン情報）</li><li>再現手順</li><li>ログ（収集方法については <a href="#view-logs">ログを確認する</a> セクションを参照）</li></ul><p>これにより、メンテナーは問題を特定して迅速に修正できます。</p>`,44)])])}const b=i(t,[["render",o]]);export{u as __pageData,b as default};
